eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\nconst blogDetailData = [\n    {\n        id_blog: 1,\n        header: \"Solusi Website Profesional untuk Bisnis Anda\",\n        header_paragraph: \"Kami menyediakan layanan pembuatan website company profile yang dirancang khusus untuk meningkatkan citra dan kehadiran online bisnis Anda. Website yang kami buat disesuaikan dengan identitas brand Anda, memberikan tampilan yang profesional, modern, dan responsif.\",\n        image: \"/images/blog/contohWebCompany.png\",\n        fitur: \"Fitur Utama Layanan Kami\",\n        link: \"https://khakenfood.my.id/\",\n        point: [\n            \"Desain Responsif: Tampilan optimal di semua perangkat, baik desktop maupun mobile.\",\n            \"Kustomisasi Brand: Desain yang disesuaikan dengan identitas brand Anda.\",\n            \"Navigasi Mudah: Struktur website yang user-friendly untuk akses cepat.\",\n            \"SEO-Friendly: Dioptimalkan untuk meningkatkan visibilitas di mesin pencari.\",\n            \"Konten Berkualitas: Penyusunan konten menarik dan informatif.\",\n            \"Keamanan Tinggi: Proteksi SSL untuk keamanan data pengunjung.\",\n            \"Integrasi Sosial Media: Koneksi langsung dengan platform media sosial.\",\n            \"Optimasi Kecepatan: Waktu loading cepat untuk pengalaman pengguna yang baik.\",\n            \"CMS Mudah: Sistem pengelolaan konten yang simpel dan fleksibel.\"\n        ],\n        end: \"Siap meningkatkan citra dan kehadiran online bisnis Anda? Hubungi kami untuk konsultasi dan informasi lebih lanjut mengenai layanan pembuatan website company profile kami. Tim kami siap membantu Anda mewujudkan website impian yang akan memberikan nilai lebih bagi bisnis Anda.\"\n    },\n    {\n        id_blog: 2,\n        header: \"Undangan Digital untuk Acara Pernikahan Anda\",\n        header_paragraph: \"Mafiin Cloud juga menyediakan layanan undangan digital berbasis website yang siap membantu Anda dalam merayakan momen spesial dengan cara yang lebih modern dan efisien. Dengan berbagai fitur menarik, kami menawarkan solusi undangan yang tidak hanya praktis, tetapi juga estetik dan ramah lingkungan.\",\n        image: \"/images/blog/wedding.png\",\n        link: \"https://momentofinahasbi.com/to/mafiin%20cloud\",\n        fitur: \"Fitur Utama Layanan Kami\",\n        point: [\n            \"Desain Kustom: Pilih dari berbagai template undangan yang dapat disesuaikan sesuai tema dan kebutuhan acara Anda, baik itu pernikahan, ulang tahun, atau acara resmi lainnya.\",\n            \"Pengiriman Mudah: Undangan digital dapat dikirim langsung melalui email, WhatsApp, atau media sosial, memastikan bahwa semua tamu Anda menerima undangan dengan cepat dan efisien.\",\n            \"RSVP Online: Memudahkan tamu untuk mengonfirmasi kehadiran mereka dengan fitur RSVP yang terintegrasi, sehingga Anda dapat merencanakan acara dengan lebih baik.\",\n            \"Konten Multimedia: Tambahkan foto, video, atau musik untuk menjadikan undangan Anda lebih hidup dan menarik.\",\n            \"Akses Mudah: Tamu dapat mengakses undangan Anda kapan saja dan di mana saja melalui perangkat apa pun, tanpa perlu mencetak kertas.\",\n            \"Keamanan Tinggi: Proteksi SSL untuk keamanan data pengunjung.\",\n            \"Integrasi Sosial Media: Koneksi langsung dengan platform media sosial.\",\n            \"Optimasi Kecepatan: Waktu loading cepat untuk pengalaman pengguna yang baik.\",\n            \"Custom Domain: Pilih domain yang sesuai dengan kebutuhan Anda.\",\n            \"Music Background: Pilih lagu yang sesuai dengan kebutuhan Anda.\",\n            \"Keamanan Data: Kami menjaga keamanan data Anda dengan sistem yang terjamin, sehingga Anda dapat tenang dalam menggunakan layanan kami.\",\n            \"Lainnya: Kami menyediakan semua fitur yang diperlukan untuk memudahkan proses undangan digital Anda.\"\n        ],\n        end: \"Siap untuk merayakan momen spesial Anda dengan undangan digital yang elegan dan praktis? Hubungi kami untuk konsultasi dan informasi lebih lanjut tentang layanan undangan digital berbasis website kami. Tim kami siap membantu Anda mewujudkan undangan impian Anda!\"\n    },\n    {\n        id_blog: 3,\n        header: \"Kelola Semua Mudah\",\n        header_paragraph: \"Kelola Semua Mudah (KSM) adalah aplikasi berbasis website yang dirancang untuk membantu perusahaan distributorship dalam mencatat, mengelola, dan memantau operasional bisnis secara terpusat, efisien, dan real-time. Solusi ini memudahkan pengelolaan stok, transaksi, gudang, hingga laporan keuangan dalam satu sistem terintegrasi.\",\n        image: \"/images/blog/ksmDashboard.png\",\n        link: \"https://kelolasemuamudah.com\",\n        fitur: \"Fitur Utama Kelola Semua Mudah\",\n        point: [\n            \"Manajemen Produk & Kategori: Kelola data produk secara terstruktur, termasuk kategori, satuan, harga beli, dan harga jual.\",\n            \"Manajemen Gudang : Mendukung Distribution Stok Keluar Masuk.\",\n            \"Kontrol Stok & Inventory: Pencatatan stok masuk, stok keluar, mutasi antar gudang, serta riwayat pergerakan barang.\",\n            \"Transaksi Pembelian (Purchase): Kelola purchase order, penerimaan barang, serta pencatatan hutang ke supplier.\",\n            \"Transaksi Penjualan (Sales): Pencatatan penjualan tunai dan Transfer, invoice, serta penagihan Klien.\",\n            \"Manajemen Supplier & Customer: Database supplier dan pelanggan lengkap dengan riwayat transaksi.\",\n            \"Manajemen Pengguna & Hak Akses: Multi role user (Admin, Gudang, Finance, Purchasing,Sales dan Driver) dengan pengaturan akses sesuai kebutuhan.\",\n            \"Laporan & Dashboard: Laporan stok, penjualan, pembelian, dan ringkasan bisnis dalam bentuk dashboard yang mudah dipahami.\",\n            \"Notifikasi & Reminder: Pemberitahuan stok menipis, Return, Refund, Pengriman Customer, Uang (Keluar,Masuk), Collection.\",\n            \"Sistem Berbasis Cloud: Akses data kapan saja dan di mana saja melalui berbagai perangkat.\",\n            \"Keamanan Data: Sistem keamanan dengan autentikasi pengguna, kontrol akses, dan backup data berkala.\"\n        ],\n        end: \"Dengan Kelola Semua Mudah, pengelolaan operasional bisnis distributorship menjadi lebih rapi, transparan, dan efisien. Hubungi kami untuk mendapatkan solusi pencatatan operasional yang sesuai dengan kebutuhan bisnis Anda.\"\n    }\n];\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (blogDetailData);\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/components/Blog/blogDetailData.tsx\n");

